using Cosmos.API.Security;using Cosmos.Application.Abstractions.Services;using Cosmos.Application.Organization;using Cosmos.Domain.Security;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace Cosmos.API.Controllers;
[Authorize,ApiExplorerSettings(GroupName="masters")]
[Route("api/v1/organization")]
public sealed class CompanyBranchesController(ICompanyBranchMasterService service):ApiControllerBase { [HttpGet("companies")][RequirePermission("System.CompanyBranchScope",PermissionAction.View)] public async Task<IActionResult> Companies(string? search,bool activeOnly,CancellationToken ct)=>FromResponse(await service.CompaniesAsync(search,activeOnly,ct)); [HttpGet("companies/{id:long}")][RequirePermission("System.CompanyBranchScope",PermissionAction.View)] public async Task<IActionResult> Company(long id,CancellationToken ct)=>FromResponse(await service.CompanyAsync(id,ct)); [HttpPost("companies")][RequirePermission("System.CompanyBranchScope",PermissionAction.Create)] public async Task<IActionResult> CreateCompany(SaveCompanyRequest r,CancellationToken ct)=>FromResponse(await service.SaveCompanyAsync(null,r,ct),201); [HttpPut("companies/{id:long}")][RequirePermission("System.CompanyBranchScope",PermissionAction.Edit)] public async Task<IActionResult> UpdateCompany(long id,SaveCompanyRequest r,CancellationToken ct)=>FromResponse(await service.SaveCompanyAsync(id,r,ct)); [HttpGet("branches")][RequirePermission("System.CompanyBranchScope",PermissionAction.View)] public async Task<IActionResult> Branches(long? companyId,string? search,bool activeOnly,CancellationToken ct)=>FromResponse(await service.BranchesAsync(companyId,search,activeOnly,ct)); [HttpGet("branches/{id:long}")][RequirePermission("System.CompanyBranchScope",PermissionAction.View)] public async Task<IActionResult> Branch(long id,CancellationToken ct)=>FromResponse(await service.BranchAsync(id,ct)); [HttpPost("branches")][RequirePermission("System.CompanyBranchScope",PermissionAction.Create)] public async Task<IActionResult> CreateBranch(SaveBranchRequest r,CancellationToken ct)=>FromResponse(await service.SaveBranchAsync(null,r,ct),201); [HttpPut("branches/{id:long}")][RequirePermission("System.CompanyBranchScope",PermissionAction.Edit)] public async Task<IActionResult> UpdateBranch(long id,SaveBranchRequest r,CancellationToken ct)=>FromResponse(await service.SaveBranchAsync(id,r,ct)); }
